"use client"

import {
  buildColorMap,
  formatPageRanges,
  toSegments,
  type Segment,
} from "@/lib/segments"
import { FileThumbnail } from "@/components/ui/file-thumbnail"
import { RunCard } from "@/components/ui/run-card"
import type { ClassifyResult } from "@/components/viewers/lib/classify-types"
import type { SplitView } from "@/components/viewers/lib/split-types"

// Each primitive's result, framed as a "run" — the same shape the workflow test
// runner shows. The thumbnail is the source document's first page; the card body
// renders the primitive's output.
const CLASSIFICATION = {
  file: { name: "loan-application.pdf", type: "application/pdf" },
  thumbnail: "/samples/loan-application-page-1.png",
  result: {
    category: "Loan Application",
    reasoning:
      "A Uniform Residential Loan Application (Form 1003): borrower, employment, and property details for a mortgage request.",
  } satisfies ClassifyResult,
}

const SPLIT = {
  file: { name: "attention.pdf", type: "application/pdf" },
  result: {
    output: [
      { name: "Title & Abstract", pages: [1] },
      { name: "Introduction", pages: [2, 3] },
      { name: "Model Architecture", pages: [4, 5, 6] },
      { name: "Results", pages: [7, 8] },
      { name: "References", pages: [9, 10, 11] },
    ],
  } satisfies SplitView,
}

// First page of each subdocument → its rendered thumbnail. A real app would
// generate these from the split output; here they're prerendered pages.
function subdocumentThumbnail(segment: Segment): string {
  return `/samples/attention-page-${segment.pages[0]}.png`
}

/**
 * Primitive run cards — one card per primitive result, built by composing the
 * `RunCard` shell (a `FileThumbnail` + status + body) with each primitive's own
 * result rendering.
 *
 * - Classification reduces to one document, so its card shows one thumbnail.
 * - A split fans one document into several subdocuments, so its card swaps the
 *   single thumbnail for a *bundle* — a row of much smaller `FileThumbnail`s, one
 *   per subdocument, color-keyed to the legend below.
 */
export function PrimitiveCardsBlock() {
  return (
    <div className="flex h-full min-h-[680px] flex-col bg-background">
      <div className="min-h-0 flex-1 overflow-auto p-6">
        <div className="mx-auto grid max-w-3xl gap-4 sm:grid-cols-2">
          <ClassificationCard />
          <SplitCard />
        </div>
      </div>
    </div>
  )
}

function ClassificationCard() {
  const { file, thumbnail, result } = CLASSIFICATION
  const color = buildColorMap([result.category]).get(result.category) ?? "#4E79A7"

  return (
    <RunCard
      file={file}
      status="completed"
      media={
        <ClassifiedThumbnail
          thumbnail={thumbnail}
          fileName={file.name}
          category={result.category}
          reasoning={result.reasoning}
          color={color}
        />
      }
    />
  )
}

/**
 * The source document with its category as a legend badge on top, and the
 * model's reasoning captioned over a scrim along the bottom.
 */
function ClassifiedThumbnail({
  thumbnail,
  fileName,
  category,
  reasoning,
  color,
}: {
  thumbnail: string
  fileName: string
  category: string
  reasoning?: string
  color: string
}) {
  return (
    <div className="relative size-full">
      <FileThumbnail
        file={{ name: fileName, type: "application/pdf" }}
        previewImageUrl={thumbnail}
        previewClassName="object-top"
        className="absolute inset-0 size-full rounded-none border-0"
      />
      <span
        className="absolute top-2 left-2 inline-flex max-w-[calc(100%-1rem)] items-center truncate rounded-md px-2 py-1 text-[11px] font-semibold shadow-sm"
        style={{ backgroundColor: color, color: readableTextColor(color) }}
        title={category}
      >
        {category}
      </span>
      {reasoning ? (
        <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/80 via-black/45 to-transparent px-3 pt-10 pb-2.5">
          <p className="line-clamp-3 text-[11px] leading-snug text-white/95">
            {reasoning}
          </p>
        </div>
      ) : null}
    </div>
  )
}

function SplitCard() {
  const { file, result } = SPLIT
  const segments = toSegments(result.output)

  return (
    <RunCard
      file={file}
      status="completed"
      media={<SubdocumentBundle segments={segments} />}
    />
  )
}

/** A centered row of small per-subdocument thumbnails — the split "bundle". */
function SubdocumentBundle({ segments }: { segments: Segment[] }) {
  return (
    <div className="bg-muted/40 flex size-full items-center justify-center gap-2 overflow-x-auto px-3 py-2">
      {segments.map((segment) => (
        <SubdocumentThumbnail key={segment.id} segment={segment} />
      ))}
    </div>
  )
}

function SubdocumentThumbnail({ segment }: { segment: Segment }) {
  const multiPage = segment.pages.length > 1

  return (
    <div className="flex w-16 shrink-0 flex-col items-center gap-1">
      <div className="relative w-full">
        {/* Offset layers behind the page imply a multi-page bundle. */}
        {multiPage ? (
          <>
            <span className="bg-card absolute inset-0 translate-x-[3px] translate-y-[3px] rounded-[4px] border" />
            <span className="bg-card absolute inset-0 translate-x-[1.5px] translate-y-[1.5px] rounded-[4px] border" />
          </>
        ) : null}
        <FileThumbnail
          file={{ name: `${segment.label}.pdf`, type: "application/pdf" }}
          previewImageUrl={subdocumentThumbnail(segment)}
          previewAspectRatio={3 / 4}
          previewClassName="object-top"
          className="relative w-full rounded-[4px] shadow-sm"
        />
        {/* The legend badge sits on top of the page, color-keyed to the split. */}
        <span
          className="absolute inset-x-0.5 top-0.5 truncate rounded px-1 py-0.5 text-center text-[9px] font-semibold shadow-sm"
          style={{
            backgroundColor: segment.color,
            color: readableTextColor(segment.color),
          }}
          title={segment.label}
        >
          {segment.label}
        </span>
      </div>
      <span className="text-muted-foreground w-full truncate text-center text-[9px] tabular-nums">
        {formatPageRanges(segment.pages)}
      </span>
    </div>
  )
}

/** Black or white text, whichever reads better on a palette color. */
function readableTextColor(hex: string): string {
  const value = hex.replace("#", "")
  const r = parseInt(value.slice(0, 2), 16)
  const g = parseInt(value.slice(2, 4), 16)
  const b = parseInt(value.slice(4, 6), 16)
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255
  return luminance > 0.62 ? "#1c1c1c" : "#ffffff"
}

"use client"

import * as React from "react"
import {
  CheckCircle2,
  Clock,
  Loader2,
  XCircle,
  type LucideIcon,
} from "lucide-react"

import { cn } from "@/lib/utils"
import {
  FileThumbnail,
  type FileThumbnailProps,
} from "@/components/ui/file-thumbnail"

export type RunStatus = "queued" | "running" | "completed" | "failed"

const RUN_STATUS: Record<
  RunStatus,
  { label: string; icon: LucideIcon; tone: string; spin?: boolean }
> = {
  queued: { label: "Queued", icon: Clock, tone: "text-muted-foreground" },
  running: {
    label: "Running",
    icon: Loader2,
    tone: "text-amber-600 dark:text-amber-500",
    spin: true,
  },
  completed: {
    label: "Completed",
    icon: CheckCircle2,
    tone: "text-emerald-600 dark:text-emerald-500",
  },
  failed: {
    label: "Failed",
    icon: XCircle,
    tone: "text-red-600 dark:text-red-500",
  },
}

export interface RunCardProps
  extends Pick<
    FileThumbnailProps,
    | "file"
    | "previewContent"
    | "previewImageUrl"
    | "previewAspectRatio"
    | "previewClassName"
    | "isLoading"
    | "hasError"
  > {
  /**
   * Replaces the single `FileThumbnail` with custom media in the same framed,
   * status-pilled slot — e.g. a bundle of per-subdocument thumbnails. The frame
   * still honors `previewAspectRatio`.
   */
  media?: React.ReactNode
  /** Lifecycle of the run — shown as a pill over the thumbnail. */
  status?: RunStatus
  /** Heading line; defaults to the file name. */
  title?: React.ReactNode
  /** Right-aligned metadata in the heading (e.g. the run kind or a timestamp). */
  meta?: React.ReactNode
  /** The run's result, rendered in the card body. */
  children?: React.ReactNode
  /** Makes the whole card a button. */
  onClick?: () => void
  className?: string
}

/**
 * A run card: a document thumbnail with a status pill, a heading, and a slot for
 * the run's result. It composes {@link FileThumbnail} for the preview surface —
 * pass a rendered page through `previewContent`, an image URL through
 * `previewImageUrl`, or let it fall back to the file-type placeholder — and
 * leaves the result rendering to its `children`, so the same card frames a
 * classification, a split, an extraction, or anything else.
 */
export function RunCard({
  file,
  previewContent,
  previewImageUrl,
  previewAspectRatio,
  previewClassName,
  isLoading,
  hasError,
  media,
  status,
  title,
  meta,
  children,
  onClick,
  className,
}: RunCardProps) {
  const interactive = typeof onClick === "function"
  // The body is optional — a card can be just media + overlays.
  const hasFooter = title != null || meta != null || children != null

  return (
    <div
      data-slot="run-card"
      role={interactive ? "button" : undefined}
      tabIndex={interactive ? 0 : undefined}
      onClick={onClick}
      onKeyDown={
        interactive
          ? (event) => {
              if (event.key === "Enter" || event.key === " ") {
                event.preventDefault()
                onClick?.()
              }
            }
          : undefined
      }
      className={cn(
        "group/run-card bg-card text-card-foreground flex flex-col overflow-hidden rounded-xl border transition-colors",
        interactive &&
          "hover:border-foreground/20 focus-visible:ring-ring cursor-pointer outline-none focus-visible:ring-2",
        className
      )}
    >
      <div className="relative">
        {media ? (
          <div
            className={cn("overflow-hidden", hasFooter && "border-b")}
            style={{ aspectRatio: String(previewAspectRatio ?? 16 / 10) }}
          >
            {media}
          </div>
        ) : (
          <FileThumbnail
            file={file}
            previewContent={previewContent}
            previewImageUrl={previewImageUrl}
            previewClassName={previewClassName}
            previewAspectRatio={previewAspectRatio ?? 16 / 10}
            isLoading={isLoading}
            hasError={hasError}
            className={cn("rounded-none border-0", hasFooter && "border-b")}
          />
        )}
        {status ? (
          <div className="absolute top-2 right-2">
            <RunStatusBadge status={status} />
          </div>
        ) : null}
      </div>

      {hasFooter ? (
        <div className="flex flex-col gap-2 p-3">
          <div className="flex min-w-0 items-center gap-2">
            <span className="min-w-0 flex-1 truncate text-sm font-medium">
              {title ?? file.name}
            </span>
            {meta ? (
              <span className="text-muted-foreground shrink-0 text-xs tabular-nums">
                {meta}
              </span>
            ) : null}
          </div>
          {children}
        </div>
      ) : null}
    </div>
  )
}

/** The status pill used in the corner of a {@link RunCard}. */
export function RunStatusBadge({
  status,
  className,
}: {
  status: RunStatus
  className?: string
}) {
  const { label, icon: Icon, tone, spin } = RUN_STATUS[status]
  return (
    <span
      className={cn(
        "bg-background/85 inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-[11px] font-medium backdrop-blur",
        tone,
        className
      )}
    >
      <Icon className={cn("size-3", spin && "animate-spin")} aria-hidden />
      {label}
    </span>
  )
}

// Classification result shape for the classifier viewer.

/** Decision shape accepted by the viewer — works with new and legacy types. */
export interface ClassifyResult {
  category: string
  reasoning?: string
}

// Split result shapes (the structural subset the viewer needs), mirrored from
// the Retab dashboard's SplitView.

import type { PartitionChunk } from "@/components/viewers/lib/partition-types"

export interface SplitResult {
  name: string
  /** 1-indexed pages assigned to this subdocument. */
  pages: number[]
  /** Frontend-only overlay carried through by the split viewer. */
  partitions?: PartitionChunk[]
}

export interface SplitViewConsensus {
  choices?: SplitResult[][]
  likelihoods?: unknown[] | null
}

export interface SplitView {
  output: SplitResult[]
  consensus?: SplitViewConsensus | null
  usage?: { credits: number } | null
}

export function asSplitView(
  payload: { output?: unknown; consensus?: unknown; usage?: unknown } | null | undefined,
): SplitView | null {
  if (!payload || !Array.isArray(payload.output)) return null
  return {
    output: payload.output as SplitResult[],
    consensus: (payload.consensus ?? null) as SplitViewConsensus | null,
    usage: (payload.usage ?? null) as SplitView["usage"],
  }
}

export function getSplitVotes(
  splitView: SplitView | null | undefined,
  splitIndex: number,
): SplitResult[] {
  const choices = splitView?.consensus?.choices
  if (!choices?.length) return []
  return choices.flatMap((choice) => {
    const split = choice[splitIndex]
    return split ? [split] : []
  })
}
